/**
 * Shared API contract: TypeScript types + Zod request/response schemas.
 * Used by the Express API (runtime validation) and the React app (types only).
 * Originally generated by Orval from docs/openapi.yaml; now maintained by hand.
 */
import * as zod from "zod";

// ============================ Types ============================

export type AuthRole = typeof AuthRole[keyof typeof AuthRole];


export const AuthRole = {
  Receptionist: 'Receptionist',
  MD: 'MD',
  COO: 'COO',
  President: 'President',
  Employee: 'Employee',
  Admin: 'Admin',
} as const;

export interface AuthUser {
  id: string;
  name: string;
  email: string;
  role: AuthRole;
  /** @nullable */
  employeeId: string | null;
  active: boolean;
  createdAt: Date;
}

export interface AuthSession {
  user: AuthUser | null;
}

export type AuthUsers = AuthUser[];

export interface AuthUserInput {
  /**
     * @minLength 1
     * @maxLength 120
     */
  name: string;
  email: string;
  /** @minLength 12 */
  password: string;
  role: AuthRole;
  /** @nullable */
  employeeId: string | null;
  active: boolean;
}

export interface AuthUserUpdate {
  /**
     * @minLength 1
     * @maxLength 120
     */
  name?: string;
  email?: string;
  /** @minLength 12 */
  password?: string;
  role?: AuthRole;
  /** @nullable */
  employeeId?: string | null;
  active?: boolean;
}

export interface AdminBootstrapInput {
  /**
     * @minLength 1
     * @maxLength 120
     */
  name: string;
  email: string;
  /** @minLength 12 */
  password: string;
  bootstrapToken?: string;
}

export interface AuthBootstrapStatus {
  available: boolean;
  requiresToken: boolean;
}

export interface AuthLogoutResult {
  success: boolean;
}

export interface Employee {
  id: string;
  name: string;
  designation: string;
  department: string;
  loginEmail: string;
  active: boolean;
  canReceiveRequests: boolean;
  canTransferRequests: boolean;
  transferTo: string[];
}

export interface EmployeeActiveUpdate {
  active: boolean;
}

export type EmployeeRequestActionAction = typeof EmployeeRequestActionAction[keyof typeof EmployeeRequestActionAction];


export const EmployeeRequestActionAction = {
  call: 'call',
  wait: 'wait',
  decline: 'decline',
} as const;

export interface EmployeeRequestAction {
  action: EmployeeRequestActionAction;
}

export interface HealthStatus {
  status: string;
}

export type MeetingRequestStatus = typeof MeetingRequestStatus[keyof typeof MeetingRequestStatus];


export const MeetingRequestStatus = {
  Waiting: 'Waiting',
  Requested: 'Requested',
  Accepted: 'Accepted',
  Transferred: 'Transferred',
  Declined: 'Declined',
  Called_In: 'Called In',
  Meeting: 'Meeting',
  Completed: 'Completed',
} as const;

export interface MeetingRequest {
  id: string;
  visitorName: string;
  mobileNumber: string;
  company: string;
  purpose: string;
  requestedEmployeeId: string;
  requestedEmployeeName: string;
  assignedEmployeeId: string;
  assignedEmployeeName: string;
  /** @minimum 1 */
  visitorCount: number;
  idVehicleNumber: string;
  remarks: string;
  requestedAt: Date;
  updatedAt: Date;
  status: MeetingRequestStatus;
}

export interface MeetingRequestInput {
  /** @minLength 1 */
  visitorName: string;
  /** @minLength 1 */
  mobileNumber: string;
  company: string;
  /** @minLength 1 */
  purpose: string;
  /** @minLength 1 */
  requestedEmployeeId: string;
  /** @minimum 1 */
  visitorCount: number;
  idVehicleNumber: string;
  remarks: string;
}

export interface LocalMigrationResult {
  imported: boolean;
  requestCount: number;
  employeeCount: number;
}

export interface LocalReceptionSnapshot {
  requests: MeetingRequest[];
  employees: Employee[];
}

export interface ReceptionSnapshot {
  requests: MeetingRequest[];
  employees: Employee[];
  migrationAvailable: boolean;
}

export type ReceptionStatusUpdateStatus = typeof ReceptionStatusUpdateStatus[keyof typeof ReceptionStatusUpdateStatus];


export const ReceptionStatusUpdateStatus = {
  Called_In: 'Called In',
  Meeting: 'Meeting',
  Completed: 'Completed',
} as const;

export interface ReceptionStatusUpdate {
  status: ReceptionStatusUpdateStatus;
}

export interface TransferRequestInput {
  /** @minLength 1 */
  targetEmployeeId: string;
}

export interface PasswordLoginInput {
  email: string;
  /** @minLength 1 */
  password: string;
}


// ========================= Zod schemas =========================
/**
 * Returns server health status
 * @summary Health check
 */
export const HealthCheckResponse = zod.object({
  "status": zod.string()
})


/**
 * @summary Check whether first-admin setup is available
 */
export const GetAuthBootstrapStatusResponse = zod.object({
  "available": zod.boolean(),
  "requiresToken": zod.boolean()
})


/**
 * @summary Create the first administrator account
 */
export const bootstrapFirstAdminBodyNameMax = 120;

export const bootstrapFirstAdminBodyPasswordMin = 12;



export const BootstrapFirstAdminBody = zod.object({
  "name": zod.string().min(1).max(bootstrapFirstAdminBodyNameMax),
  "email": zod.string().email(),
  "password": zod.string().min(bootstrapFirstAdminBodyPasswordMin),
  "bootstrapToken": zod.string().optional()
})

export const BootstrapFirstAdminResponse = zod.object({
  "user": zod.union([zod.object({
  "id": zod.string(),
  "name": zod.string(),
  "email": zod.string().email(),
  "role": zod.enum(['Receptionist', 'MD', 'COO', 'President', 'Employee', 'Admin']),
  "employeeId": zod.string().nullable(),
  "active": zod.boolean(),
  "createdAt": zod.coerce.date()
}),zod.null()])
})


/**
 * @summary Sign in with an authorized account
 */



export const LoginBody = zod.object({
  "email": zod.string().email(),
  "password": zod.string().min(1)
})

export const LoginResponse = zod.object({
  "user": zod.union([zod.object({
  "id": zod.string(),
  "name": zod.string(),
  "email": zod.string().email(),
  "role": zod.enum(['Receptionist', 'MD', 'COO', 'President', 'Employee', 'Admin']),
  "employeeId": zod.string().nullable(),
  "active": zod.boolean(),
  "createdAt": zod.coerce.date()
}),zod.null()])
})


